<script setup>
import {onMounted,ref,computed} from 'vue'
import {Search,Download,ClipboardCheck,ArrowDownUp} from 'lucide-vue-next'
import {rpc,data} from '../transport'
import {notice} from '../state'
const rows=ref([]),search=ref(''),filter=ref('all'),selected=ref([])
const visible=computed(()=>rows.value.filter(r=>(filter.value==='all'||r.state===filter.value)&&r.title.toLowerCase().includes(search.value.toLowerCase())))
onMounted(async()=>{try{rows.value=(await rpc('protocols.list')).rows||[]}catch(e){notice(e.message)}})
function exportCsv(){const list=selected.value.length?visible.value.filter(r=>selected.value.includes(r.id)):visible.value;const blob=new Blob(['\ufeffSpecimen;Zeit;Pressure;Pressure drop;Result\n'+list.map(r=>[r.title,r.created,data(r).pressure,data(r).drop,r.state].join(';')).join('\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pruefprotokolle.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><div><div class="compact-intro"><div><div class="eyebrow">QUALITY ASSURANCE</div><h1>Inspection reports</h1><p>Results from the simulated valve test bench.</p></div><button class="button outline" :disabled="!rows.length" @click="exportCsv"><Download :size="16"/> Export CSV</button></div><div class="stats-row"><div><span>Tests</span><strong>{{rows.length}}</strong></div><div><span>Passed</span><strong>{{rows.filter(r=>r.state==='passed').length}}</strong></div><div><span>Rework</span><strong>{{rows.filter(r=>r.state==='failed').length}}</strong></div></div><div class="panel table-panel"><div class="table-toolbar"><h2>Inspection reports</h2><div class="table-filters"><label class="search-field"><Search :size="17"/><input v-model="search" placeholder="Search specimens" aria-label="Search specimens"></label><select v-model="filter" aria-label="Filter results"><option value="all">All results</option><option value="passed">Passed</option><option value="failed">Rework</option></select></div></div><div class="table-scroll"><table><thead><tr><th></th><th>Specimen</th><th>Test bench</th><th>Pressure</th><th>Pressure drop</th><th>Result</th><th>Timestamp</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td><input v-model="selected" :value="r.id" type="checkbox" :aria-label="r.title+' select'"></td><td><strong>{{r.title}}</strong><small>Coolant valve KV-24</small></td><td>VP-01</td><td>{{data(r).pressure?.toFixed(2)}} bar</td><td>{{data(r).drop?.toFixed(3)}} bar</td><td><span class="tag" :class="r.state==='passed'?'success':'warning'">{{r.state==='passed'?'Passed':'Rework'}}</span></td><td>{{r.created}}</td></tr></tbody></table></div><div v-if="!visible.length" class="empty-state"><ClipboardCheck :size="34"/><h3>{{rows.length?'No matching results.':'No inspection reports yet.'}}</h3><p>Start a valve test cycle. The result will appear here.</p><RouterLink class="button secondary" to="/machines/valve-leak-test">Open test bench</RouterLink></div><div class="table-footer">{{visible.length}} Resultse <span v-if="selected.length">{{selected.length}} selected</span></div></div></div></template>
